output_text:
[
  {
    "id": "return_cart_to_top_left_bay",
    "text": "Before leaving the store, the shopper must return the cart to the designated return bay at the top-left cell.",
    "abstraction": {
      "state_properties": {
        "withCart": "hasCart",
        "atReturnBay": "at(0,1)",
        "cartInReturnBay": "cartAt(0,1)"
      },
      "events": {
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "withCart",
              "atReturnBay"
            ]
          },
          "post": "cartInReturnBay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "items_trigger_cart_return",
    "text": "After picking up any required item, the shopper is obliged to return the cart to the top-left cart bay before the trip ends.",
    "abstraction": {
      "state_properties": {
        "withCart": "hasCart",
        "atReturnBay": "at(0,1)",
        "cartInReturnBay": "cartAt(0,1)"
      },
      "events": {
        "item_loaded": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "withCart"
            ]
          },
          "post": "withCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "withCart",
              "atReturnBay"
            ]
          },
          "post": "cartInReturnBay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_loaded",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_cart_abandonment_outside_bay",
    "text": "A shopper may not leave a cart anywhere except in the designated top-left return bay.",
    "abstraction": {
      "state_properties": {
        "atReturnBay": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "atReturnBay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is prohibited from exiting the supermarket while still pushing or holding a cart.",
    "abstraction": {
      "state_properties": {
        "withCart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "withCart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "must_use_cart_for_item_pickups",
    "text": "Items must be picked up only while the shopper has a cart, rather than being carried directly by hand.",
    "abstraction": {
      "state_properties": {
        "withCart": "hasCart"
      },
      "events": {
        "hand_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "withCart"
              }
            ]
          },
          "post": null
        },
        "cart_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "withCart"
            ]
          },
          "post": "withCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "hand_pickup"
    }
  },
  {
    "id": "no_hand_carrying_merchandise",
    "text": "A shopper may not be in a state of carrying merchandise by hand.",
    "abstraction": {
      "state_properties": {
        "carryingByHand": "handFull",
        "withCart": "hasCart"
      },
      "events": {
        "become_hand_full": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "withCart"
              }
            ]
          },
          "post": "carryingByHand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carryingByHand"
    }
  },
  {
    "id": "take_entrance_cart",
    "text": "At the start of a shopping trip, the shopper must take the available entrance cart before continuing the trip.",
    "abstraction": {
      "state_properties": {
        "atEntranceCart": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "withCart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "PICKUP_CART",
              "atEntranceCart"
            ]
          },
          "post": "withCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "carts_banned_from_exit_side",
    "text": "Shopping carts are prohibited in the eastern exit-side area of the store.",
    "abstraction": {
      "state_properties": {
        "withCart": "hasCart",
        "exitSideArea": {
          "or": [
            "at(7,0)",
            "at(7,1)",
            "at(7,2)",
            "at(7,3)",
            "at(7,4)",
            "at(7,5)",
            "at(8,0)",
            "at(8,1)",
            "at(8,2)",
            "at(8,3)",
            "at(8,4)",
            "at(8,5)",
            "at(9,0)",
            "at(9,1)",
            "at(9,2)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        }
      },
      "events": {
        "cart_enters_exit_side": {
          "pre": {
            "and": [
              "MOVE",
              "withCart"
            ]
          },
          "post": {
            "and": [
              "withCart",
              "exitSideArea"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "withCart",
          "exitSideArea"
        ]
      }
    }
  }
]
